public class BalancedTreesTour {
    static class Node {
        int key, height = 0;
        Node left, right;
        Node(int key) { this.key = key; }
    }

    static int h(Node n) { return n == null ? -1 : n.height; }
    static void fix(Node n) { n.height = 1 + Math.max(h(n.left), h(n.right)); }

    static Node rotateRight(Node y) { Node x = y.left; y.left = x.right; x.right = y; fix(y); fix(x); return x; }
    static Node rotateLeft(Node x) { Node y = x.right; x.right = y.left; y.left = x; fix(x); fix(y); return y; }

    static Node plainInsert(Node n, int key) {
        if (n == null) return new Node(key);
        if (key < n.key) n.left = plainInsert(n.left, key); else n.right = plainInsert(n.right, key);
        fix(n);
        return n;
    }

    static Node avlInsert(Node n, int key) {
        if (n == null) return new Node(key);
        if (key < n.key) n.left = avlInsert(n.left, key); else n.right = avlInsert(n.right, key);
        fix(n);
        int balance = h(n.left) - h(n.right);
        if (balance > 1) {                                   // left-heavy
            if (key > n.left.key) n.left = rotateLeft(n.left);
            return rotateRight(n);
        }
        if (balance < -1) {                                  // right-heavy
            if (key < n.right.key) n.right = rotateRight(n.right);
            return rotateLeft(n);
        }
        return n;
    }

    public static void main(String[] args) {
        Node plain = null, avl = null;
        for (int key = 1; key <= 1000; key++) {               // sorted input: the worst case for a plain BST
            plain = plainInsert(plain, key);
            avl = avlInsert(avl, key);
            if (key == 15 || key == 1000) {
                System.out.println(key + " sorted keys: plain BST height " + h(plain) + ", AVL height " + h(avl));
            }
        }
        System.out.println("an AVL tree stays within 1.44 * log2(n): a search needs at most " + (h(avl) + 1) + " comparisons");
    }
}

