import java.util.ArrayDeque;
import java.util.Deque;

public class AvlTree {
    static class Node {
        int key, height = 0;
        Node left, right;
        Node(int key) { this.key = key; }
    }

    static int h(Node n) { return n == null ? -1 : n.height; }
    static int balance(Node n) { return h(n.left) - h(n.right); }
    static void fix(Node n) { n.height = 1 + Math.max(h(n.left), h(n.right)); }

    static Node rotateRight(Node y) { Node x = y.left; y.left = x.right; x.right = y; fix(y); fix(x); return x; }
    static Node rotateLeft(Node x) { Node y = x.right; x.right = y.left; y.left = x; fix(x); fix(y); return y; }

    static Node insert(Node n, int key) {
        if (n == null) return new Node(key);
        if (key < n.key) n.left = insert(n.left, key); else n.right = insert(n.right, key);
        fix(n);
        int b = balance(n);
        if (b > 1 && key < n.left.key) { report("LL", n); return rotateRight(n); }
        if (b < -1 && key > n.right.key) { report("RR", n); return rotateLeft(n); }
        if (b > 1) { report("LR", n); n.left = rotateLeft(n.left); return rotateRight(n); }
        if (b < -1) { report("RL", n); n.right = rotateRight(n.right); return rotateLeft(n); }
        return n;
    }

    static void report(String kind, Node n) {
        System.out.println("  node " + n.key + " has balance " + balance(n) + ": case " + kind);
    }

    static String levels(Node root) {
        StringBuilder sb = new StringBuilder();
        Deque<Node> q = new ArrayDeque<>();
        q.add(root);
        while (!q.isEmpty()) {
            for (int i = q.size(); i > 0; i--) {
                Node n = q.poll();
                sb.append(n.key).append('(').append(balance(n)).append(") ");
                if (n.left != null) q.add(n.left);
                if (n.right != null) q.add(n.right);
            }
            sb.append("| ");
        }
        return sb.substring(0, sb.length() - 3);
    }

    public static void main(String[] args) {
        Node root = null;
        for (int key : new int[]{30, 20, 10, 40, 50, 25, 5, 7}) {
            System.out.println("insert " + key);
            root = insert(root, key);
            System.out.println("  " + levels(root));
        }
        System.out.println("height " + h(root) + " for 8 keys");
    }
}

