public class RedBlackTree {
    static final boolean RED = true, BLACK = false;

    static class Node {
        int key;
        Node left, right;
        boolean color = RED;                       // new nodes are red
        Node(int key) { this.key = key; }
    }

    static boolean isRed(Node n) { return n != null && n.color == RED; }

    static Node rotateLeft(Node h) { Node x = h.right; h.right = x.left; x.left = h; x.color = h.color; h.color = RED; return x; }
    static Node rotateRight(Node h) { Node x = h.left; h.left = x.right; x.right = h; x.color = h.color; h.color = RED; return x; }
    static void flipColors(Node h) { h.color = RED; h.left.color = BLACK; h.right.color = BLACK; }

    static Node insert(Node h, int key) {
        if (h == null) return new Node(key);
        if (key < h.key) h.left = insert(h.left, key);
        else if (key > h.key) h.right = insert(h.right, key);
        if (isRed(h.right) && !isRed(h.left)) h = rotateLeft(h);         // lean left
        if (isRed(h.left) && isRed(h.left.left)) h = rotateRight(h);     // two reds in a row
        if (isRed(h.left) && isRed(h.right)) flipColors(h);              // split a 4-node
        return h;
    }

    static boolean noRedRed(Node n) {
        if (n == null) return true;
        if (isRed(n) && (isRed(n.left) || isRed(n.right))) return false;
        return noRedRed(n.left) && noRedRed(n.right);
    }

    static int blackHeight(Node n) {             // -1 if the paths disagree
        if (n == null) return 0;
        int l = blackHeight(n.left), r = blackHeight(n.right);
        if (l < 0 || r < 0 || l != r) return -1;
        return l + (isRed(n) ? 0 : 1);
    }

    static int height(Node n) { return n == null ? -1 : 1 + Math.max(height(n.left), height(n.right)); }

    public static void main(String[] args) {
        Node root = null;
        for (int key = 1; key <= 15; key++) {
            root = insert(root, key);
            root.color = BLACK;                    // the root is always black
            if (key % 3 == 0) {
                System.out.printf("after %2d keys: height %d, black height %d, no red-red: %s%n",
                        key, height(root), blackHeight(root), noRedRed(root));
            }
        }
        System.out.println("root " + root.key + ", bound 2*log2(n+1) = 8, plain BST height would be 14");
    }
}

