import java.util.ArrayList;
import java.util.List;

public class BTree {
    static final int T = 2, MAX = 2 * T - 1;      // up to 3 keys per node

    static class Node {
        List<Integer> keys = new ArrayList<>();
        List<Node> children = new ArrayList<>();
        boolean leaf() { return children.isEmpty(); }
    }

    static Node root = new Node();

    static void splitChild(Node parent, int i) {   // parent.children[i] is full
        Node full = parent.children.get(i), right = new Node();
        int middle = full.keys.get(T - 1);
        right.keys.addAll(full.keys.subList(T, MAX));
        if (!full.leaf()) right.children.addAll(full.children.subList(T, MAX + 1));
        full.keys.subList(T - 1, MAX).clear();
        if (!full.leaf()) full.children.subList(T, MAX + 1).clear();
        parent.keys.add(i, middle);                // the middle key moves up
        parent.children.add(i + 1, right);
        System.out.println("  split: " + middle + " moves up, halves " + full.keys + " and " + right.keys);
    }

    static void insert(int key) {
        if (root.keys.size() == MAX) {             // full root: the tree grows one level
            Node fresh = new Node();
            fresh.children.add(root);
            root = fresh;
            splitChild(root, 0);
        }
        Node n = root;
        while (!n.leaf()) {
            int i = 0;
            while (i < n.keys.size() && key > n.keys.get(i)) i++;
            if (n.children.get(i).keys.size() == MAX) {   // split before stepping down
                splitChild(n, i);
                if (key > n.keys.get(i)) i++;
            }
            n = n.children.get(i);
        }
        int i = 0;
        while (i < n.keys.size() && key > n.keys.get(i)) i++;
        n.keys.add(i, key);
    }

    static String levels() {
        StringBuilder sb = new StringBuilder();
        List<Node> level = List.of(root);
        while (!level.isEmpty()) {
            List<Node> next = new ArrayList<>();
            for (Node n : level) { sb.append(n.keys); next.addAll(n.children); }
            sb.append(next.isEmpty() ? "" : " / ");
            level = next;
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        for (int key : new int[]{10, 20, 5, 6, 12, 30, 7, 17, 3, 25}) {
            System.out.println("insert " + key);
            insert(key);
            System.out.println("  " + levels());
        }
        long t = 50, capacity = 1;                 // worst case: every node holds only t-1 keys
        int levels = 0;
        while (2 * capacity * t - 1 <= 1_000_000_000L) { capacity *= t; levels++; }   // height h needs >= 2t^h - 1 keys
        System.out.println("t = 50: a billion keys need at most " + levels + " levels below the root");
    }
}

public class SplayTree {
    static class Node {
        int key;
        Node left, right;
        Node(int key) { this.key = key; }
    }

    static Node rotateRight(Node y) { Node x = y.left; y.left = x.right; x.right = y; return x; }
    static Node rotateLeft(Node x) { Node y = x.right; x.right = y.left; y.left = x; return y; }

    // Brings key (or the last node on its search path) to the root
    static Node splay(Node root, int key) {
        if (root == null || root.key == key) return root;
        if (key < root.key) {
            if (root.left == null) return root;
            if (key < root.left.key) {                          // zig-zig (left-left)
                root.left.left = splay(root.left.left, key);
                root = rotateRight(root);
            } else if (key > root.left.key) {                   // zig-zag (left-right)
                root.left.right = splay(root.left.right, key);
                if (root.left.right != null) root.left = rotateLeft(root.left);
            }
            return root.left == null ? root : rotateRight(root);   // zig
        } else {
            if (root.right == null) return root;
            if (key > root.right.key) {                         // zig-zig (right-right)
                root.right.right = splay(root.right.right, key);
                root = rotateLeft(root);
            } else if (key < root.right.key) {                  // zig-zag (right-left)
                root.right.left = splay(root.right.left, key);
                if (root.right.left != null) root.right = rotateRight(root.right);
            }
            return root.right == null ? root : rotateLeft(root);
        }
    }

    static Node bstInsert(Node n, int key) {                    // plain insert, no splaying
        if (n == null) return new Node(key);
        if (key < n.key) n.left = bstInsert(n.left, key); else n.right = bstInsert(n.right, key);
        return n;
    }

    static int depth(Node n, int key) {
        int d = 0;
        while (n.key != key) { n = key < n.key ? n.left : n.right; d++; }
        return d;
    }

    static int height(Node n) { return n == null ? -1 : 1 + Math.max(height(n.left), height(n.right)); }

    public static void main(String[] args) {
        Node root = null;
        for (int key = 9; key >= 1; key--) root = bstInsert(root, key);   // a left-leaning chain
        System.out.println("chain of 9 keys: height " + height(root) + ", root " + root.key);
        for (int key : new int[]{1, 1, 5, 2, 9}) {
            int before = depth(root, key);
            root = splay(root, key);
            System.out.println("access " + key + ": depth before " + before + ", now root " + root.key + ", height " + height(root));
        }
    }
}

