import java.util.ArrayList;
import java.util.List;

public class TreeRotations {
    static class Node {
        int key;
        Node left, right;
        Node(int key, Node left, Node right) { this.key = key; this.left = left; this.right = right; }
    }

    static Node rotateRight(Node y) {
        Node x = y.left;
        y.left = x.right;      // the middle subtree B changes parent
        x.right = y;
        return x;              // x is the new subtree root
    }

    static Node rotateLeft(Node x) {
        Node y = x.right;
        x.right = y.left;
        y.left = x;
        return y;
    }

    static String shape(Node n) {
        if (n == null) return "-";
        if (n.left == null && n.right == null) return String.valueOf(n.key);
        return "(" + shape(n.left) + " " + n.key + " " + shape(n.right) + ")";
    }

    static void inorder(Node n, List<Integer> out) {
        if (n == null) return;
        inorder(n.left, out);
        out.add(n.key);
        inorder(n.right, out);
    }

    static int height(Node n) { return n == null ? -1 : 1 + Math.max(height(n.left), height(n.right)); }

    static void show(String label, Node root) {
        List<Integer> keys = new ArrayList<>();
        inorder(root, keys);
        System.out.printf("%-22s %-32s height %d, inorder %s%n", label, shape(root), height(root), keys);
    }

    public static void main(String[] args) {
        //            40
        //          /    \
        //        20      50
        //       /  \
        //     10    30
        //    /
        //   5
        Node root = new Node(40,
                new Node(20, new Node(10, new Node(5, null, null), null), new Node(30, null, null)),
                new Node(50, null, null));
        show("start:", root);
        root = rotateRight(root);
        show("rotateRight at 40:", root);
        root = rotateLeft(root);
        show("rotateLeft at 20:", root);
    }
}

