class Node:
    def __init__(self, key, left=None, right=None):
        self.key = key
        self.left = left
        self.right = right


def bst_from(keys):
    # Plain BST insertion, no balancing.
    root = None
    for k in keys:
        if root is None:
            root = Node(k)
            continue
        node = root
        while True:
            side = 'left' if k < node.key else 'right'
            child = getattr(node, side)
            if child is None:
                setattr(node, side, Node(k))
                break
            node = child
    return root


def preorder(node):
    return [node.key] + preorder(node.left) + preorder(node.right) if node else []


def is_balanced(root):
    def height(node):
        # Height of the subtree, or -1 as soon as it is unbalanced.
        if node is None:
            return 0
        left = height(node.left)
        right = height(node.right)
        if left < 0 or right < 0 or abs(left - right) > 1:
            return -1
        return 1 + max(left, right)

    return height(root) >= 0
